end

function OverseaChatClubRecruitPanel:__delete()
    self._receiveRecruitMsgEvent = nil
    self._recruitData            = nil
end

function OverseaChatClubRecruitPanel:Awake()
    self:InitHandler()
end

function OverseaChatClubRecruitPanel:OnEnable()
    self:RefreshListView()
end

function OverseaChatClubRecruitPanel:OnDisable()
    ---防止占内存，清理一次
    self:ClearListView()
    Events.RemoveListener(ChatConstants.EventNames.NEW_CLUB_RECRUIT_MESSAGE, self._receiveRecruitMsgEvent)
end

function OverseaChatClubRecruitPanel:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
