---cell加入按钮点击回调
function OverseaChatClubRecruitPanel:CellJoinBtnOnClickHandler(index)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id4001)
    if not isUnlock then
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id4001))
        return
    end
    
    local isJoinClub   = ClubUtils.GetClubComp():IsJoinClub()
    if isJoinClub then
        GameUtils.Toast(localize("不能重复加入社团"))
        return
    end
    local data = self:GetRecruitData()[index]
    local clubComp = ClubUtils.GetClubComp()

--[[    if data.isApplied then
        GameUtils.Toast(localize('已发送申请，请耐心等待'))
        return
    end]]

    if data.applyPermission.levelLimit > GameUtils.GetPlayerLevel() then
        GameUtils.Toast(localize('未达到申请要求等级'))
        return
    end

    local leftJoinSeconds = clubComp:GetQuitTimestamp() - os.time()
    if leftJoinSeconds > 0 then
        GameUtils.Toast(localize('还有_time_才能加入社团', {_time_ = CfUtils.GetTimeHMS10(leftJoinSeconds)}))
        return
    end

    if checkInt(data.memberNum) >= checkInt(data.memberNumLimit) then
        GameUtils.Toast(localize('社团已经满员'))
        return
    end

    local requestData = {clubId = data.clubId}
    GameUtils.Request(Interfaces.OverseaClubApply, requestData, function(request, response)
        if checkInt(response.errCode) == 0 then
            --[[data.isApplied = true
            local cellNode = self.ScrollView:GetShownItemByItemIndex(index - 1)
            if isNotNull(cellNode) then
                ---@type OverseaChatClubRecruitPanelCell
                local cellEnv = CfUtils.GetLuaScr(cellNode, "Game.OverseaChat.OverseaChatClubRecruitPanelCell")
                cellEnv:SetApplied(true)
            end]]

            if  checkNumber(response.data.applyStatus) == 2 then
                clubComp:InitialClubData({clubId = requestData.clubId})
            else
                GameUtils.Toast(localize('已发送申请，请等级审核'))
            end
        end
    end)
end

---列表刷新
function OverseaChatClubRecruitPanel:OnGetItemByIndex(gridView, index)
    if index < 0 then return end

    local position = index + 1
    local data = self:GetRecruitData()[position]
    if not data then return end

    local cell = gridView:NewListViewItem(PrefabCellName)
    local scr = CfUtils.GetLuaScr(cell, "Game.OverseaChat.OverseaChatClubRecruitPanelCell")
    if isNotNull(scr) then
        scr:RefreshCell(data, position, Bind(self, self.CellJoinBtnOnClickHandler))
    end
    return cell
end
--endregion handler

--region public
---刷新界面
function OverseaChatClubRecruitPanel:Refresh(env)
    self:RefreshUI()
end
--endregion public

--region private
---刷新ui
function OverseaChatClubRecruitPanel:RefreshUI()
    self:RefreshListView()
end

---刷新列表
function OverseaChatClubRecruitPanel:RefreshListView()
    if isNull(self.ScrollView) then return end

    ---@type Social
    local socialLine = AppService:GetInstance():GetSocialLine()
    local data = checkTable(socialLine.recruitClubData)
    self:SetRecruitData(data)

    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(#data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #data)
    end
    self.ScrollView:MovePanelToItemByIndex(0, 0, 0)
end

---清空列表
function OverseaChatClubRecruitPanel:ClearListView()
    if isNull(self.ScrollView) then return end
    if self.ScrollView.IsListViewInit then
        GameUtils.ReloadData(self.ScrollView, 0)
    end
end
--endregion private

--region get / set
---设置招募数据
---@param recruitData table 招募数据
function OverseaChatClubRecruitPanel:SetRecruitData(recruitData)
    self._recruitData = checkTable(recruitData)
end

---获取招募数据
function OverseaChatClubRecruitPanel:GetRecruitData()
    return self._recruitData
end

--endregion get / set

return OverseaChatClubRecruitPanel